loom_public_page('Reset password','Choose a new password using a valid one-time LOOM recovery link.',
'<section class="card"><h2>Choose a new password</h2><form id="resetForm" style="display:grid;gap:10px;max-width:520px"><input id="resetPassword" type="password" minlength="8" autocomplete="new-password" required placeholder="New password · 8+ characters" style="padding:12px;border:1px solid #d5e3d8;border-radius:10px;font:inherit"><input id="resetConfirm" type="password" minlength="8" autocomplete="new-password" required placeholder="Confirm new password" style="padding:12px;border:1px solid #d5e3d8;border-radius:10px;font:inherit"><button type="submit" style="border:0;border-radius:10px;padding:12px 16px;background:#173f27;color:#fff;font-weight:900;cursor:pointer">Replace password</button><div id="resetMsg" style="min-height:22px;color:#52675a;font-size:13px;line-height:1.5">Checking reset link…</div></form></section><script>document.addEventListener("DOMContentLoaded",async()=>{const token=new URLSearchParams(location.search).get("token")||"",f=document.getElementById("resetForm"),m=document.getElementById("resetMsg"),btn=f?.querySelector("button");async function post(body){const r=await fetch("api/email.php",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)}),j=await r.json().catch(()=>({}));if(!r.ok||j.ok===false)throw new Error(j.error||"Request failed");return j}try{const v=await post({action:"validate-reset",token});if(!v.valid)throw new Error("This reset link is invalid or expired.");m.textContent="Reset link verified.";}catch(e){m.textContent=e.message;btn.disabled=true;}f?.addEventListener("submit",async e=>{e.preventDefault();const p=document.getElementById("resetPassword").value,c=document.getElementById("resetConfirm").value;if(p!==c){m.textContent="Passwords do not match.";return}btn.disabled=true;m.textContent="Replacing password…";try{const j=await post({action:"reset-password",token,password:p});m.innerHTML=(j.message||"Password changed.")+" <a href=\"home/\">Return to LOOM</a>";}catch(err){m.textContent=err.message;btn.disabled=false}})})</script>','reset-password.php',false,true);
